(4713865, 679393, 79955, '<td valign="top">Need to control the highlights in your background. Focus is also slightly off.<br/>- one way would be to expose for the background &amp; use fill flash to light the front of the camera.</td>', 'Need to control the highlights in your background. Focus is also slightly off.- one way would be to expose for the background & use fill flash to light the front of the camera.', '2008-05-21 00:59:40.000000', NULL, 1),
(4713912, 679707, 15407, '<td valign="top">Removing the filter would likely have produced a better shot ~ less glare there.</td>', 'Removing the filter would likely have produced a better shot ~ less glare there.', '2008-05-21 01:21:16.000000', NULL, 1),
(4713916, 678728, 15407, '<td valign="top">Fliping it may have gotten you another point from many...?</td>', 'Fliping it may have gotten you another point from many...?', '2008-05-21 01:25:10.000000', NULL, 1),
(4713923, 679442, 15407, '<td valign="top">MinMy Canon will keep on ''clickin'' when it falls in the water... Too many of mine have met their death that way!  Great Picture... 2 more than a Portrait of a camera though!</td>', 'MinMy Canon will keep on ''clickin'' when it falls in the water... Too many of mine have met their death that way!  Great Picture... 2 more than a Portrait of a camera though!', '2008-05-21 01:30:06.000000', NULL, 1),
