(4718241, 679632, 90658, '<td valign="top">The reflection is magnificent.</td>', 'The reflection is magnificent.', '2008-05-22 20:33:28.000000', NULL, 1),
(4718245, 679869, 90658, '<td valign="top">I wish this were crisper.  Do you have a macro lens?  (You probably do, and you probably used it...I''m not a photog so don''t listen to me.)  :)</td>', 'I wish this were crisper.  Do you have a macro lens?  (You probably do, and you probably used it...I''m not a photog so don''t listen to me.)  :)', '2008-05-22 20:35:04.000000', NULL, 1),
